<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount } from 'vue';import { Head } from '@inertiajs/vue3';import { locale } from '../../i18n';import LanguageSwitcher from '../../components/LanguageSwitcher.vue';import RichField from '../../components/website/RichField.vue';import PageSections from '../../components/website/PageSections.vue';import SiteHeader from '../../components/website/SiteHeader.vue';import Icon from '../../components/website/Icon.vue';import iconData from '../../components/website/icons.json';import type { Block, SiteDocument } from '../../components/website/types';
type Page={slug:string;version:number;published_revision:string|null;document:SiteDocument};const props=defineProps<{page:Page;pages:{slug:string;version:number;published:boolean}[];revisions:{id:string;created_at:number;actor:string}[]}>();const tr=(id:string,en:string)=>locale.value==='id'?id:en;const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const doc=ref(clone(props.page.document)),version=ref(props.page.version),language=ref<'id'|'en'>('id'),selection=ref(0),drag=ref<number|null>(null),newSlug=ref(''),busy=ref(false),dirty=ref(false),error=ref(''),notice=ref(''),uncertain=ref(false),preview=ref(false),mobile=ref(false),reviewed=ref(false),fileInput=ref<HTMLInputElement|null>(null);
const snapshot=ref<{document:SiteDocument;version:number;digest:string}|null>(null),pending=ref<Record<string,unknown>|null>(null);const current=computed(()=>doc.value[language.value]),block=computed(()=>current.value.blocks[selection.value]),locked=computed(()=>busy.value||uncertain.value);const icons=Object.keys(iconData.icons);
watch(doc,()=>{dirty.value=true;reviewed.value=false;snapshot.value=null;},{deep:true,flush:'sync'});watch(language,()=>{selection.value=0;});function guard(e:BeforeUnloadEvent){if(dirty.value||uncertain.value||busy.value){e.preventDefault();e.returnValue='';}}window.addEventListener('beforeunload',guard);onBeforeUnmount(()=>window.removeEventListener('beforeunload',guard));
function headers(){return {'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''};}
async function mutate(body:Record<string,unknown>){if(busy.value)return false;pending.value??=clone({operation_id:crypto.randomUUID(),...body});busy.value=true;error.value='';notice.value='';try{const r=await fetch('/platform/site/'+props.page.slug,{method:'POST',credentials:'same-origin',headers:headers(),body:JSON.stringify(pending.value),signal:AbortSignal.timeout(25000)});if(r.status>=500)throw new Error();const data=await r.json();if(!r.ok){pending.value=null;uncertain.value=false;error.value=r.status===403?tr('Verifikasi kata sandi dan authenticator di tab Keamanan control plane, lalu coba lagi.','Verify your password and authenticator in the control-plane Security tab, then retry.'):JSON.stringify(data).includes('STALE_VERSION')?tr('Draft berubah di sesi lain. Muat ulang sebelum melanjutkan.','This draft changed in another session. Reload before continuing.'):tr('Perubahan ditolak. Periksa isian dan ukuran konten.','Change rejected. Check the fields and content size.');return false;}const action=pending.value?.action;version.value=data.record.version;if(data.record.document)doc.value=clone(data.record.document);dirty.value=false;pending.value=null;uncertain.value=false;snapshot.value=null;reviewed.value=false;notice.value=action==='publish'?tr('Halaman berhasil dipublikasikan.','Page published successfully.'):tr('Draft tersimpan. Halaman publik belum berubah.','Draft saved. The public page has not changed.');return true;}catch{uncertain.value=true;error.value=tr('Hasil penyimpanan belum pasti. Ulangi permintaan yang sama.','The save result is uncertain. Retry the same request.');return false;}finally{busy.value=false;}}
async function save(){return mutate({action:'save',version:version.value,document:doc.value});}async function openPreview(){if(dirty.value||version.value===0){if(!await save())return;}busy.value=true;error.value='';try{const r=await fetch(`/platform/site/${props.page.slug}/preview?format=json`,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error();const data=await r.json();if(data.version!==version.value)throw new Error();snapshot.value=data;reviewed.value=false;preview.value=true;}catch{error.value=tr('Pratinjau belum tersedia. Muat ulang jika draft berubah.','Preview unavailable. Reload if the draft changed.');}finally{busy.value=false;}}
async function publish(){if(!snapshot.value||!reviewed.value||dirty.value)return;const ok=await mutate({action:'publish',version:snapshot.value.version,digest:snapshot.value.digest,reviewed:true});if(ok)preview.value=false;}
function move(from:number,to:number){if(locked.value||to<0||to>=current.value.blocks.length)return;const [item]=current.value.blocks.splice(from,1);current.value.blocks.splice(to,0,item);selection.value=to;drag.value=null;}
function add(type:Block['type']){if(current.value.blocks.length>=24)return;current.value.blocks.push({id:'block-'+crypto.randomUUID().slice(0,8),type,tone:'light',eyebrow:'',title:tr('Bagian baru','New section'),body:'<p>'+tr('Tulis narasi Anda di sini.','Write your story here.')+'</p>',image:'',alt:'',button:'',href:'/register',items:[]});selection.value=current.value.blocks.length-1;}
function remove(){if(current.value.blocks.length<=1)return;current.value.blocks.splice(selection.value,1);selection.value=Math.max(0,selection.value-1);}function changePage(slug:string){if((dirty.value||uncertain.value)&&!window.confirm(tr('Tinggalkan perubahan yang belum tersimpan?','Leave unsaved changes?')))return;dirty.value=false;window.location.assign('/platform/site/'+slug);}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!block.value)return;if(file.size>3*1024*1024){error.value=tr('Gambar maksimal 3 MB.','Maximum image size is 3 MB.');return;}const target=block.value;busy.value=true;error.value='';try{const form=new FormData();form.append('image',file);const r=await fetch('/platform/site/media',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':headers()['X-CSRF-TOKEN']},body:form,signal:AbortSignal.timeout(25000)});if(!r.ok)throw new Error();const data=await r.json();target.image=data.record.id;notice.value=tr('Gambar diunggah. Simpan draft untuk memasangnya.','Image uploaded. Save the draft to use it.');}catch{error.value=tr('Unggah belum terkonfirmasi. Gunakan JPG/PNG/WebP maksimal 3 MB dan periksa verifikasi keamanan. Mengunggah ulang file yang sama aman.','Upload not confirmed. Use JPG/PNG/WebP up to 3 MB and check security verification. Retrying the same file is safe.');}finally{busy.value=false;if(fileInput.value)fileInput.value.value='';}}
</script>
<template><div class="site-editor"><Head title="Website studio | oneQay"/><header class="editor-top"><div><a href="/platform">← Control plane</a><h1><Icon name="panel-top" :size="23"/>{{ tr('Studio website','Website studio') }} <small>oneQay</small></h1></div><div class="editor-top-actions"><LanguageSwitcher/><a class="editor-security" href="/platform#security" target="_blank" rel="noopener"><Icon name="shield-check" :size="15"/>{{ tr('Verifikasi keamanan','Security verification') }}</a><button :disabled="locked" @click="save"><Icon name="save" :size="15"/>{{ tr('Simpan draft','Save draft') }}</button><button class="primary" :disabled="locked" @click="openPreview"><Icon name="eye" :size="16"/>{{ tr('Pratinjau & publikasi','Preview & publish') }}</button></div></header><div v-if="error" class="editor-notice error" role="alert">{{ error }} <button v-if="uncertain&&pending" :disabled="busy" @click="mutate(pending)">{{ tr('Ulangi permintaan yang sama','Retry same request') }}</button></div><div v-if="notice" class="editor-notice" role="status">{{ notice }}</div><div class="editor-workspace"><aside class="editor-sidebar"><label>{{ tr('Halaman','Page') }}<select :value="page.slug" :disabled="locked" @change="changePage(($event.target as HTMLSelectElement).value)"><option v-for="p in pages" :key="p.slug" :value="p.slug">{{ p.slug==='navigation'?tr('Menu navigasi','Navigation menu'):p.slug }}{{ p.published?'':' · draft' }}</option><option v-if="!pages.some(p=>p.slug===page.slug)" :value="page.slug">{{ page.slug }}</option></select></label><form class="new-page" @submit.prevent="changePage(newSlug)"><input v-model="newSlug" :aria-label="tr('Alamat halaman baru','New page slug')" placeholder="halaman-baru" required pattern="[a-z][a-z0-9-]{0,63}" maxlength="64" :disabled="locked"/><button :disabled="locked" :aria-label="tr('Tambah halaman','Add page')"><Icon name="plus" :size="16"/></button></form><div class="editor-language"><button :class="{selected:language==='id'}" @click="language='id'">Indonesia</button><button :class="{selected:language==='en'}" @click="language='en'">English</button></div><div class="draft-meta"><span></span>{{ dirty?tr('Belum disimpan','Unsaved changes'):tr('Draft tersimpan','Saved draft') }} · v{{ version }}</div><h2>{{ tr('Susunan halaman','Page sections') }}</h2><p class="editor-hint">{{ tr('Seret bagian atau gunakan panah untuk mengatur urutan.','Drag a section or use the arrows to reorder.') }}</p><ol class="block-list"><li v-for="(b,i) in current.blocks" :key="b.id" :draggable="!locked" :class="{selected:selection===i}" @dragstart="drag=i" @dragover.prevent @drop.prevent="drag!==null&&move(drag,i)" @dragend="drag=null"><button class="block-select" @click="selection=i"><Icon name="grip-vertical" :size="15"/><span>{{ b.title||b.type }}<small>{{ b.type }}</small></span></button><div><button :disabled="locked||i===0" :aria-label="tr('Naik','Move up')" @click="move(i,i-1)"><Icon name="arrow-up" :size="12"/></button><button :disabled="locked||i===current.blocks.length-1" :aria-label="tr('Turun','Move down')" @click="move(i,i+1)"><Icon name="arrow-down" :size="12"/></button></div></li></ol><label>{{ tr('Tambah bagian','Add section') }}<select :disabled="locked||current.blocks.length>=24" value="" @change="add(($event.target as HTMLSelectElement).value as Block['type']);($event.target as HTMLSelectElement).value=''"><option value="" disabled>{{ tr('Pilih jenis bagian…','Choose section type…') }}</option><option value="hero">Hero</option><option value="features">{{ tr('Kartu fitur / menu','Feature cards / menu') }}</option><option value="split">{{ tr('Gambar & narasi','Image & story') }}</option><option value="text">{{ tr('Teks','Text') }}</option><option value="faq">FAQ</option><option value="cta">{{ tr('Ajakan bertindak','Call to action') }}</option><option value="pricing">{{ tr('Paket harga','Pricing cards') }}</option></select></label><details class="editor-history"><summary>{{ tr('Riwayat publikasi','Publication history') }}</summary><p v-if="!revisions.length" class="editor-hint">{{ tr('Belum ada versi publikasi. Muat ulang setelah publikasi untuk melihat riwayat terbaru.','No published revisions. Reload after publication to see the latest history.') }}</p><div v-for="r in revisions" :key="r.id"><small>{{ new Date(r.created_at*1000).toLocaleString() }}</small><button :disabled="locked||dirty" @click="mutate({action:'restore',version,revision:r.id})"><Icon name="undo-2" :size="12"/>{{ tr('Pulihkan ke draft','Restore to draft') }}</button></div></details></aside><section class="editor-fields"><fieldset :disabled="locked"><details class="page-seo"><summary>{{ tr('Judul & informasi halaman','Page title & information') }}</summary><label>{{ tr('Judul halaman','Page title') }}<input v-model="current.title" maxlength="160"/></label><label>{{ tr('Deskripsi pencarian','Search description') }}<textarea v-model="current.description" maxlength="320" rows="3"></textarea></label></details><template v-if="block"><div class="section-heading"><h2>{{ tr('Edit bagian','Edit section') }}</h2><button :disabled="current.blocks.length<=1" @click="remove"><Icon name="trash-2" :size="13"/>{{ tr('Hapus','Remove') }}</button></div><label>{{ tr('Label kecil','Eyebrow') }}<input v-model="block.eyebrow" maxlength="100"/></label><label>{{ tr('Judul','Heading') }}<textarea v-model="block.title" maxlength="220" rows="3"></textarea></label><RichField :key="language+block.id" v-model="block.body" :disabled="locked" :label="tr('Narasi','Body text')"/><label>{{ tr('Warna bagian','Section tone') }}<select v-model="block.tone"><option value="light">{{ tr('Putih','White') }}</option><option value="soft">{{ tr('Biru muda','Light blue') }}</option><option value="dark">{{ tr('Biru gelap','Dark blue') }}</option></select></label><label>{{ tr('Gambar','Image') }}<input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" @change="upload"/></label><p class="editor-hint">JPG, PNG, WebP · {{ tr('maksimal 3 MB','up to 3 MB') }}</p><div v-if="block.image" class="editor-image"><img :src="'/platform/site/media/'+block.image" :alt="block.alt"/><button @click="block.image=''">{{ tr('Lepaskan gambar','Remove image') }}</button></div><label>{{ tr('Deskripsi gambar','Image description') }}<input v-model="block.alt" maxlength="220"/></label><label>{{ tr('Teks tombol','Button text') }}<input v-model="block.button" maxlength="60"/></label><label>{{ tr('Tautan tombol','Button link') }}<input v-model="block.href" maxlength="150" placeholder="/register"/></label><p class="editor-hint">/register · /business-login · /pages/slug · #section</p><template v-if="['features','faq','pricing'].includes(block.type)"><h3>{{ tr('Daftar kartu / menu','Cards / menu items') }}</h3><div v-for="(item,i) in block.items" :key="i" class="item-fields"><label>{{ tr('Judul item','Item title') }} {{ i+1 }}<input v-model="item.title" maxlength="160"/></label><label>{{ tr('Keterangan','Description') }}<textarea v-model="item.body" maxlength="1200" rows="3"></textarea></label><label>{{ tr('Tautan','Link') }}<input v-model="item.href" maxlength="150"/></label><label>Iconify / Lucide<select v-model="item.icon"><option v-for="ic in icons" :key="ic" :value="ic">{{ ic }}</option></select></label><button @click="block.items.splice(i,1)">{{ tr('Hapus item','Remove item') }}</button></div><button :disabled="block.items.length>=16" @click="block.items.push({title:tr('Item baru','New item'),body:'',href:'/register',icon:'store'})"><Icon name="plus" :size="14"/>{{ tr('Tambah item','Add item') }}</button></template></template></fieldset></section><section class="editor-canvas"><div class="canvas-toolbar"><span>{{ tr('Tampilan langsung','Live canvas') }} · {{ language.toUpperCase() }}</span><span>{{ tr('Konten draft','Draft content') }}</span></div><div class="canvas-sheet oneqay-site"><PageSections :page="current" preview/></div></section></div><div v-if="preview&&snapshot" class="preview-overlay" role="dialog" aria-modal="true" :aria-label="tr('Pratinjau publikasi','Publication preview')" @keydown.esc="preview=false"><div class="preview-toolbar"><strong>{{ tr('Tinjau sebelum dipublikasikan','Review before publishing') }}</strong><div><button @click="mobile=!mobile"><Icon :name="mobile?'monitor':'smartphone'" :size="16"/>{{ mobile?'Desktop':'Mobile' }}</button><select v-model="language" aria-label="Preview language"><option value="id">Indonesia</option><option value="en">English</option></select><button :disabled="busy" @click="preview=false">{{ tr('Tutup','Close') }}<Icon name="x" :size="16"/></button></div></div><div class="preview-scroll"><div class="preview-sheet oneqay-site" :class="{mobile}"><SiteHeader v-if="page.slug==='navigation'" :navigation="snapshot.document"/><PageSections :page="snapshot.document[language]" preview/></div></div><div class="publish-bar"><label><input v-model="reviewed" type="checkbox"/>{{ tr('Saya sudah meninjau konten Indonesia dan English.','I have reviewed the Indonesian and English content.') }}</label><button class="primary" :disabled="!reviewed||locked" @click="publish">{{ tr('Publikasikan sekarang','Publish now') }}<Icon name="arrow-up-right" :size="17"/></button></div></div></div></template>
<style>
.site-editor{font:14px/1.5 Inter,system-ui,sans-serif;color:#233853;background:#edf1f7;min-height:100vh}.site-editor *{box-sizing:border-box}.site-editor button,.site-editor input,.site-editor textarea,.site-editor select{font:inherit}.site-editor button{display:inline-flex;align-items:center;justify-content:center;gap:7px;cursor:pointer;border:1px solid #cfd9e8;border-radius:7px;background:#fff;color:#254367;padding:9px 13px;font-size:12px;font-weight:600}.site-editor button.primary{background:#245fd2;color:#fff;border-color:#245fd2}.site-editor button:disabled{opacity:.45;cursor:not-allowed}.editor-top{display:flex;align-items:center;justify-content:space-between;gap:20px;background:white;border-bottom:1px solid #dbe3ee;padding:18px 26px}.editor-top a{color:#677992;font-size:11px;text-decoration:none}.editor-top h1{display:flex;align-items:center;gap:10px;font-size:22px;margin:5px 0 0;letter-spacing:-.6px}.editor-top h1 small{font-size:13px;font-weight:500;color:#7c8da5;margin-left:8px}.editor-top-actions{display:flex;align-items:center;gap:12px}.editor-security{display:flex;gap:6px;align-items:center}.editor-workspace{display:grid;grid-template-columns:250px 310px minmax(0,1fr);min-height:calc(100vh - 100px)}.editor-sidebar,.editor-fields{background:#fff;padding:22px 18px;border-right:1px solid #dce4ef;min-width:0}.editor-fields{background:#fbfcff}.site-editor label,.site-editor .field-label{display:block;font-size:11px;font-weight:650;margin:0 0 17px}.site-editor input:not([type=checkbox]),.site-editor textarea,.site-editor select{display:block;width:100%;border:1px solid #d1dcea;border-radius:6px;padding:10px;margin-top:6px;background:#fff;color:#233853;font-size:12px}.site-editor textarea{resize:vertical}.new-page{display:flex;gap:5px;margin:-6px 0 20px}.new-page input{margin:0!important}.editor-language{display:flex;gap:5px}.editor-language button{flex:1;font-size:11px}.editor-language button.selected{color:#245fd2;background:#e9f1ff;border-color:#abc4ee}.draft-meta{font-size:10px;color:#75839a;margin:16px 0 25px;display:flex;gap:7px;align-items:center}.draft-meta>span{width:5px;height:5px;background:#edaf51;border-radius:50%}.site-editor h2{font-size:14px;margin:15px 0 10px}.site-editor h3{font-size:13px}.editor-hint{font-size:10px;color:#72839d;line-height:1.7}.block-list{list-style:none;padding:0;margin:20px 0}.block-list li{display:flex;align-items:center;border:1px solid #e0e6f0;border-radius:7px;margin:8px 0;background:#fff;padding:5px}.block-list li.selected{border-color:#94b5ec;background:#edf4ff}.block-list .block-select{border:0;background:none;padding:5px;justify-content:flex-start;flex:1;min-width:0;text-align:left;font-size:11px}.block-select>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.block-select small{display:block;font-size:9px;font-weight:400;color:#8295af}.block-list li>div{display:flex;flex-direction:column}.block-list li>div>button{padding:3px 5px;font-size:10px;border:0;background:transparent}.site-editor fieldset{padding:0;border:0;margin:0;min-width:0}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.section-heading button{font-size:10px;padding:6px 10px;color:#ad5443}.page-seo{border-bottom:1px solid #dfe7f1;padding-bottom:20px;margin-bottom:20px}.page-seo summary,.editor-history summary{cursor:pointer;font-size:11px;font-weight:650}.page-seo label:first-of-type{margin-top:20px}.rich-field{margin-bottom:20px}.rich-toolbar{display:flex;gap:4px;border:1px solid #d1dcea;border-bottom:0;background:#f0f4f9;padding:5px;border-radius:6px 6px 0 0}.rich-toolbar button{padding:5px 8px}.rich-content{min-height:130px;max-height:350px;overflow:auto;background:white;border:1px solid #d1dcea;padding:12px;font-size:12px;border-radius:0 0 6px 6px;outline-color:#245fd2}.rich-content p{margin:0 0 10px}.rich-content ul{padding-left:20px}.editor-image{border:1px solid #dce5f2;padding:8px;background:#fff;border-radius:6px;margin:10px 0}.editor-image img{width:100%;max-height:140px;object-fit:contain}.editor-image button{font-size:10px;width:100%}.editor-fields input[type=file]{font-size:10px}.item-fields{padding:12px;border:1px solid #dce4ef;border-radius:7px;margin-bottom:15px;background:#fff}.item-fields label{font-size:10px}.item-fields button{font-size:10px}.editor-canvas{padding:20px;min-width:0}.canvas-toolbar{display:flex;justify-content:space-between;color:#7a8ca6;font-size:10px;padding:0 4px 14px}.canvas-sheet{box-shadow:0 3px 18px #1f39670b;border-radius:8px;overflow:hidden}.editor-canvas .oneqay-site .wrap{width:calc(100% - 48px)}.editor-canvas .section-split{grid-template-columns:1fr;gap:25px}.editor-canvas .site-section{padding:40px 0}.editor-canvas .site-section h1{font-size:34px}.editor-canvas .site-section h2{font-size:27px}.editor-canvas .feature-grid,.editor-canvas .feature-grid.three-columns{grid-template-columns:repeat(2,1fr)}.editor-canvas .section-copy{order:0}.editor-canvas .section-visual{max-width:450px;margin:auto}.editor-canvas .site-eyebrow{font-size:8px}.editor-canvas .site-prose{font-size:12px}.editor-canvas .floating-receipt{right:-5px}.editor-history{border-top:1px solid #e1e8f1;margin-top:30px;padding-top:20px}.editor-history>div{margin-top:12px}.editor-history small{display:block;color:#8294ae;font-size:10px}.editor-history button{font-size:10px;padding:5px;margin-top:5px}.editor-notice{background:#edf8f3;color:#247354;padding:14px 25px;font-size:12px;border-bottom:1px solid #cce4d9}.editor-notice.error{background:#fff3e6;color:#935b27;border-color:#f2dfc4}.editor-notice button{margin-left:10px}.preview-overlay{position:fixed;inset:0;background:#e7ecf5;z-index:100;display:flex;flex-direction:column}.preview-toolbar,.publish-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 25px;background:#fff;border-bottom:1px solid #d5dfeb}.preview-toolbar>div{display:flex;align-items:center;gap:10px}.preview-toolbar select{margin:0;width:auto}.preview-scroll{overflow:auto;flex:1;padding:25px}.preview-sheet{max-width:1280px;margin:auto}.preview-sheet.mobile{max-width:390px}.preview-sheet.mobile .wrap{width:calc(100% - 38px)}.preview-sheet.mobile .section-split,.preview-sheet.mobile .feature-grid{grid-template-columns:1fr}.preview-sheet.mobile h1,.preview-sheet.mobile h2{font-size:34px}.preview-sheet.mobile .section-copy{order:0}.preview-sheet.mobile .site-section{padding:40px 0}.preview-sheet.mobile .section-actions{flex-wrap:wrap}.publish-bar{border-top:1px solid #d5dfeb;border-bottom:0}.publish-bar label{display:flex;align-items:center;gap:10px;margin:0;font-size:12px}.site-editor :focus-visible{outline:3px solid #ddb36c;outline-offset:3px}@media(max-width:1200px){.editor-workspace{grid-template-columns:220px 280px minmax(0,1fr)}.editor-canvas .feature-grid{grid-template-columns:1fr}.editor-security{display:none}.editor-top{padding:15px}.editor-top-actions{gap:7px}}@media(max-width:950px){.editor-workspace{grid-template-columns:230px 1fr}.editor-canvas{grid-column:1/-1}.editor-top{flex-wrap:wrap}.editor-top-actions{flex-wrap:wrap}.preview-toolbar{flex-wrap:wrap}.publish-bar{align-items:stretch;flex-direction:column;gap:12px}}@media(max-width:550px){.editor-workspace{grid-template-columns:1fr}.editor-sidebar{border-bottom:1px solid #dce4ef}.block-list{max-height:240px;overflow:auto}.editor-canvas{padding:12px}.editor-top-actions{width:100%}.editor-top-actions button{font-size:11px;padding:9px}.preview-scroll{padding:10px}.preview-toolbar{padding:12px}.preview-toolbar strong{font-size:12px}}
</style>
